"""Build the concise, self-contained supervisor demo brief in French and English."""

import base64
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
FIGURE = ROOT / "prototype/trajectory-accuracy/t11-joined-trajectory.png"
IMAGE = "data:image/png;base64," + base64.b64encode(FIGURE.read_bytes()).decode("ascii")

CSS = """
:root{--ink:#172e38;--muted:#52646b;--teal:#087f78;--gold:#bb7914;--coral:#ac5148;--line:#d5dfdc;--paper:#fffdf8;--ice:#eaf5f2}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#eef2ef;color:var(--ink);font:16px/1.5 system-ui,-apple-system,sans-serif}
main{max-width:1100px;margin:28px auto;padding:46px 55px;background:var(--paper);box-shadow:0 12px 40px #14313c16;border-radius:16px}
header{border-bottom:2px solid var(--line);padding-bottom:25px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;color:var(--teal);font-size:12px;font-weight:800}
h1,h2,h3{font-family:Georgia,serif;line-height:1.15}h1{font-size:clamp(36px,4vw,58px);max-width:850px;margin:14px 0}h2{font-size:29px;margin:0 0 14px}h3{font-size:21px;margin:0 0 8px}.lead{font-size:19px;max-width:850px;margin:0;color:#344d53}
.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:27px 0}.metric{border:1px solid var(--line);border-top:5px solid var(--teal);border-radius:9px;background:white;padding:15px}.metric:nth-child(2){border-color:#e8d5b1;border-top-color:var(--gold)}.metric:nth-child(3){border-color:#ead7d3;border-top-color:var(--coral)}.metric strong{display:block;font:700 32px/1.15 Georgia,serif;margin-bottom:7px}.metric span{font-size:13px;color:var(--muted)}
section{margin:31px 0}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.step{padding:18px;border:1px solid var(--line);border-radius:10px;background:#fff}.step .num{display:inline-block;color:var(--teal);font-weight:800;font-size:12px;letter-spacing:.1em;margin-bottom:10px}.step p{margin:0;font-size:14px;color:#3d555a}
.strategy{background:var(--ice);border-left:5px solid var(--teal);padding:22px 25px;border-radius:9px}.strategy p{margin:8px 0}.numbers{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.numbers div{background:white;border:1px solid var(--line);border-radius:8px;padding:11px;font-size:14px}.numbers b{display:block;font-size:15px}.numbers span{color:var(--muted);font-size:12px}.small{font-size:13px;color:var(--muted)}
figure{margin:0}figure img{display:block;width:100%;height:auto;border:1px solid var(--line);border-radius:8px;background:#fff}figcaption{color:var(--muted);font-size:13px;margin-top:10px}.takeaway{background:#17323a;color:#fff;padding:22px 26px;border-radius:10px;font:20px/1.45 Georgia,serif}.takeaway p{margin:0}.takeaway b{color:#94ded2}.links{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.links a{display:inline-block;background:#fff;border:1px solid #a7c2be;border-radius:7px;padding:9px 12px;text-decoration:none;color:#075f5b;font-weight:700;font-size:13px}a{color:#096e68}footer{border-top:1px solid var(--line);padding-top:18px;font-size:13px;color:var(--muted)}
@media(max-width:760px){main{margin:0;padding:27px 20px;border-radius:0}.metrics,.steps,.numbers{grid-template-columns:1fr}}
@page{size:A4;margin:13mm}@media print{body{background:#fff}main{max-width:none;margin:0;padding:0;box-shadow:none}.metric,.step,.strategy,figure,.takeaway{break-inside:avoid}a{color:var(--ink)}}
"""

FR = f"""<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projet curling · démonstration superviseur</title><style>{CSS}</style><main>
<header><div class="eyebrow">Projet curling · point d'étape · 9 octobre 2026</div><h1>Détecter les lancers, puis suivre la pierre</h1><p class="lead">La démonstration tient en trois résultats : les passages sont retrouvés sur la manche de développement, un filtre réduit les fausses alertes sur des extraits étudiés, et T11 est visible dans les deux caméras.</p></header>
<div class="metrics"><div class="metric"><strong>16 / 16</strong><span>Passages appariés, sans candidat supplémentaire, sur la manche Canada–Corée utilisée pour le développement.</span></div><div class="metric"><strong>19 / 1 / 1</strong><span>VP / FP / FN sur 18,5 minutes Canada–États-Unis ; F1 temporel 0,95 sur une référence préparée par l'agent.</span></div><div class="metric"><strong>0,61 m</strong><span>Écart longitudinal nominal entre les deux projections de T11 dans la même image à 46,7 s.</span></div></div>
<section><h2>Ce que fait le prototype</h2><div class="steps"><div class="step"><span class="num">01 · PASSAGE</span><h3>Repérer un lancer</h3><p>Un suivi bref de pierre colorée en mouvement franchit une ligne virtuelle. L'événement est un repère de passage, pas l'instant exact du lâcher.</p></div><div class="step"><span class="num">02 · TRI</span><h3>Garder puis filtrer</h3><p>La première étape conserve des propositions pour le rappel. Un contrôle de contexte visuel réduit les faux candidats ; ceux qui échouent restent vérifiables.</p></div><div class="step"><span class="num">03 · TRAJECTOIRE</span><h3>Comparer deux vues</h3><p>T11 fournit 31 positions au départ et 29 à l'arrivée, dont 15 points lointains expérimentaux. Les deux courbes restent séparées pour rendre l'écart visible.</p></div></div></section>
<section class="strategy" id="recall-filter"><h2>Le choix technique : rappel d'abord, précision ensuite</h2><p>Un filtre sévère peut masquer de vrais lancers manqués. Nous conservons donc les propositions brutes, puis confirmons celles dont le passage se situe dans le couloir d'image attendu, dont le mouvement alentour reste compact et qui ne répètent pas un passage récent.</p><div class="numbers"><div><b>États-Unis : 19/20/1 → 19/1/1</b><span>VP/FP/FN, brut → filtré</span></div><div><b>Estonie : 16/5/1 → 16/0/1</b><span>VP/FP/FN, brut → filtré</span></div><div><b>Chine : 17/9/1 → 17/1/1</b><span>VP/FP/FN, brut → filtré</span></div></div><p class="small">Sur ces extraits déjà étudiés, le filtre conserve les passages appariés tout en retirant des fausses alertes. Chaque liste brute manque encore un passage annoté : le filtre ne peut pas retrouver un événement jamais proposé. Il ne s'agit pas d'un score indépendant sur une partie entière. <a href="validation/two-stage-throw-audit/index.html">Voir l'audit</a>.</p></section>
<section><h2>T11 : les deux caméras montrent la pierre</h2><figure><img src="{IMAGE}" alt="Trajectoires de T11 dans les deux caméras ; leurs positions nominales diffèrent de 0,61 m dans la même image."><figcaption>Le blanc de 5,8 s du premier traitement provenait surtout d'une limite de projection de la caméra d'arrivée. Après élargissement ciblé, les deux vues produisent un point à 46,7 s. Leur différence de 0,61 m n'est pas une erreur mesurée contre la vraie position : la géométrie au loin et l'identité entre caméras restent à valider.</figcaption></figure><div class="links"><a href="prototype/throw-analysis/index.html">Voir les 16 passages ↗</a><a href="prototype/cross-view/index.html">Explorer T11 dans les deux vues ↗</a><a href="prototype/trajectory-accuracy/index.html">Voir l'analyse de trajectoire ↗</a></div></section>
<section class="takeaway"><p><b>À dire en réunion :</b> « Sur une manche de développement, nous détectons les 16 passages de pierres repérés. Notre stratégie combine des propositions à fort rappel et un filtre qui retire beaucoup de fausses alertes sur trois extraits étudiés. T11 est suivi dans deux caméras ; leur désaccord de 0,61 m montre précisément ce qu'il faut calibrer avant de prétendre à une trajectoire physique. »</p></section>
<footer><strong>Portée :</strong> les références de ces extraits ont été préparées par l'équipe de développement. Ni l'instant physique du lâcher, ni une fin de lancer générale, ni la précision métrique au loin ne sont validés. Étape suivante : annoter indépendamment des parties complètes et mesurer précision et rappel après gel des règles. <a href="validation/throw-event-benchmark/canada-usa-2024/RESULTS.html">Résultat Canada–États-Unis</a>.</footer>
</main></html>"""

EN = f"""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Curling project · supervisor demonstration</title><style>{CSS}</style><main>
<header><div class="eyebrow">Curling project · progress update · 9 October 2026</div><h1>Detect the throw, then follow the stone</h1><p class="lead">Three results carry this demonstration: passages are found on the development end, a filter reduces false alarms on studied excerpts, and T11 is visible in both cameras.</p></header>
<div class="metrics"><div class="metric"><strong>16 / 16</strong><span>Matched passages, with no extra candidate, on the Canada–Korea development end.</span></div><div class="metric"><strong>19 / 1 / 1</strong><span>TP / FP / FN on 18.5 minutes of Canada–USA; timing F1 0.95 against an agent-prepared reference.</span></div><div class="metric"><strong>0.61 m</strong><span>Nominal longitudinal disagreement between T11's two projections in the same frame at 46.7 s.</span></div></div>
<section><h2>What the prototype does</h2><div class="steps"><div class="step"><span class="num">01 · PASSAGE</span><h3>Find a throw</h3><p>A short track of a moving coloured stone crosses a virtual line. The event marks a passage, not the exact release instant.</p></div><div class="step"><span class="num">02 · SCREEN</span><h3>Keep, then filter</h3><p>The first stage retains proposals for recall. A visual-context check reduces false candidates; withheld proposals remain reviewable.</p></div><div class="step"><span class="num">03 · PATH</span><h3>Compare two views</h3><p>T11 provides 31 departure positions and 29 receiving positions, including 15 experimental far-range points. The paths remain separate so their disagreement stays visible.</p></div></div></section>
<section class="strategy" id="recall-filter"><h2>The technical choice: recall first, precision second</h2><p>A severe filter can hide real missed throws. We therefore retain raw proposals, then confirm those that cross the expected image corridor, show compact nearby motion, and do not repeat a recent passage.</p><div class="numbers"><div><b>USA: 19/20/1 → 19/1/1</b><span>TP/FP/FN, raw → filtered</span></div><div><b>Estonia: 16/5/1 → 16/0/1</b><span>TP/FP/FN, raw → filtered</span></div><div><b>China: 17/9/1 → 17/1/1</b><span>TP/FP/FN, raw → filtered</span></div></div><p class="small">On these already studied excerpts, the filter keeps matched passages while removing false alarms. Each raw pool still misses one labelled passage: a filter cannot recover an event never proposed. These are not independent full-match scores. <a href="validation/two-stage-throw-audit/index.html">View the audit</a>.</p></section>
<section><h2>T11: both cameras show the stone</h2><figure><img src="{IMAGE}" alt="T11 paths from both cameras; their nominal positions disagree by 0.61 metres in the same frame."><figcaption>The initial processing's 5.8-second blank mainly came from a receiving-camera projection limit. With a targeted range extension, both views provide a point at 46.7 s. Their 0.61 m difference is not error measured against the true position: far-range geometry and cross-camera identity remain unvalidated.</figcaption></figure><div class="links"><a href="prototype/throw-analysis/index.html">See the 16 passages ↗</a><a href="prototype/cross-view/index.html">Explore T11 in both views ↗</a><a href="prototype/trajectory-accuracy/index.html">Inspect the trajectory ↗</a></div></section>
<section class="takeaway"><p><b>Say this in the meeting:</b> “On one development end, we detect all 16 marked stone passages. Our approach combines recall-oriented proposals with a filter that removes many false alarms on three studied excerpts. T11 is tracked in both cameras; their 0.61 m disagreement shows exactly what must be calibrated before claiming a physical trajectory.”</p></section>
<footer><strong>Scope:</strong> references for these excerpts were prepared by the developing team. Physical release time, a general throw-end detector, and far-range metric accuracy remain unvalidated. Next: independently label complete matches and measure precision and recall after freezing the rules. <a href="validation/throw-event-benchmark/canada-usa-2024/RESULTS.html">Canada–USA result</a>.</footer>
</main></html>"""

FULL_MATCH_FR = """<section class="strategy"><h2>Une partie complète : de l’événement à l’état de jeu</h2><p>Nous avons traité les 2 h 19 min de Canada–Chine 2022. La chronologie contient <b>125 propositions d’événements</b> ; le livre officiel compte <b>125 lancers</b>, mais cette égalité ne mesure pas la précision de l’appariement. Un compteur diffusé relie provisoirement 114 propositions à un lancer numéroté. Pour chacun des 125 lancers, le PDF officiel fournit un plateau après lancer ; un balayage vidéo de tout le match produit 28 plateaux partiels stables, complétés par deux plateaux d’un audit ciblé antérieur. Dans la première comparaison des 27 plateaux liés sans ambiguïté au livre officiel, 106 des 115 pierres émises correspondent et 16 plateaux sont complets. Ce contrôle reste un résultat de développement. Trente-trois propositions ont un indice visuel de départ et cinq une couleur concordante entre les vues. Le livre officiel indique le sens de rotation de 123 lancers, mais pas leur nombre de tours. Aucune n’a une trajectoire physique complète ou un état prêt pour la simulation.</p><div class="links"><a href="prototype/full-match-canada-china/index.html">Explorer le match complet et les états de jeu ↗</a><a href="prototype/full-match-canada-china/rink-perspective.html">Voir la piste en perspective ↗</a></div><p class="small">Le plateau officiel est une référence indépendante, pas une reconstruction de la vidéo. Une piste en perspective visualise déjà les états discrets ; simuler réellement les lancers exige identité, position métrique continue, rotation et collisions.</p></section>"""
FULL_MATCH_EN = """<section class="strategy"><h2>One complete match: from events to game state</h2><p>We processed the 2h19m Canada–China 2022 recording. Its timeline has <b>125 provisional events</b>; the official book also lists <b>125 shots</b>, but matching totals do not measure event accuracy. Broadcast counters provisionally link 114 proposals to numbered shots. The official PDF supplies a post-shot board for all 125 shots; a full-match video scan supplies 28 stable partial boards, supplemented by two from an earlier targeted audit. In the first comparison of 27 unambiguously linked boards, 106 of 115 emitted stones matched official symbols and 16 boards were complete. This remains a development check. Thirty-three proposals have a visible start cue and five have matching colours across views. The official ledger records turn direction for 123 shots, but not revolution counts. None has a complete physical trajectory or a simulation-ready state.</p><div class="links"><a href="prototype/full-match-canada-china/index.html">Explore the full match and game states ↗</a><a href="prototype/full-match-canada-china/rink-perspective.html">View the perspective rink ↗</a></div><p class="small">The official board is an independent reference, not a video reconstruction. A perspective rink now displays the discrete states; physical replay still needs persistent identity, continuous metric position, rotation and collisions.</p></section>"""
FR = FR.replace('<section class="takeaway">', FULL_MATCH_FR + '<section class="takeaway">', 1)
EN = EN.replace('<section class="takeaway">', FULL_MATCH_EN + '<section class="takeaway">', 1)
(ROOT / "supervisor-progress-2026-10-09.html").write_text(FR)
(ROOT / "supervisor-progress-2026-10-09.en.html").write_text(EN)
print("Wrote concise French and English demo briefs")
